reference_solution:
def longest_common_subsequence(left, right):
    row = [0] * (len(right) + 1)
    for a in left:
        previous, next_row = row, [0]
        for j, b in enumerate(right, 1):
            next_row.append(previous[j - 1] + 1 if a == b else max(previous[j], next_row[-1]))
        row = next_row
    return row[-1]

